mapper.insert:
INSERT INTO board
(
  title      -- 제목
, content    -- 내용
, user_no    -- 작성자
, writer_pw  -- 글 비밀번호
, ref        -- 글 그룹
, re_lev     -- 그룹 깊이
, sort_ord     -- 그룹 순서
, hit        -- 조회수
, parent_no  -- 부모글 번호(원글일시 NULL)
, reg_date   -- 등록일
)
VALUES
(
  #{title}
, #{content}
, #{userNo}
, #{writerPw}
, #{ref}
, #{reLev}
, #{sortOrd}
, 0
, #{parentNo}
, NOW()
)

